{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C14", "C15", "C03", "C04", "C11", "C17", "C66", "C56", "C65"],
  "contradictory_card_ids": ["C21", "C31", "C29", "C42"],
  "prediction_basis_card_ids": ["C14", "C15", "C03", "C04", "C11", "C17", "C66", "C56", "C65"],
  "claims": [
    {
      "claim": "Direct human oral bioavailability values for structurally related beta2 agonists are below the 20% threshold: salbutamol 7.2% and 11.4% in fasting subjects (C14, C15), bambuterol about 10% (C03, C04, C11), and epanolol 5.85 ± 2.55% with food (C17).",
      "card_ids": ["C14", "C15", "C03", "C04", "C11", "C17"]
    },
    {
      "claim": "For the related lipophilic beta2 agonist batefenterol, oral parent exposure was negligible after a 200 µg oral dose, with all parent concentrations non-quantifiable and pooled parent AUC0-t of 0.614 h·pgEq/mL (C66, C56, C65).",
      "card_ids": ["C66", "C56", "C65"]
    },
    {
      "claim": "L5 contains no vilanterol-specific gut-wall efflux or intestinal metabolism measurement; salbutamol P-gp data were inconclusive (C176), labetalol showed P-gp-mediated efflux (C154, C151), and isoprenaline underwent intestinal sulfate excretion (C185), but these are mechanistically indirect and low-transferability for the query.",
      "card_ids": ["C176", "C154", "C151", "C185"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C176", "C154", "C151", "C185"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No matched oral-versus-IV exposure or IV reference for the query.",
    "No query-specific gut-wall efflux or intestinal metabolism measurement; L5 closest records are for salbutamol, labetalol, and isoprenaline, not vilanterol.",
    "Transfer from salbutamol, bambuterol, epanolol, and batefenterol is structural/pharmacological, not exact.",
    "Phenylephrine L2 absolute values around 38% conflict with its qualitative L1 poor outcome and are less transferable.",
    "No formulation-specific oral pharmacokinetic data for the query."
  ],
  "decision_summary": "L5 adds only indirect gut-wall efflux and intestinal metabolism records for other beta-amino alcohol/phenol compounds, with no vilanterol-specific measurement; it does not overturn the prior low prediction based on direct human oral bioavailability values below 20% for salbutamol, bambuterol, and epanolol, and negligible oral parent exposure for batefenterol. Prediction remains low with moderate confidence."
}

